extracted_python_code:
active_customers_by_country = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == 'Active')
).PARTITION(name="country_groups", by=country).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
).PARTITION(
    name="type_groups", by=(transaction_type)
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(3, by=num_distinct_customers.DESC())

result = Transactions.WHERE(transaction_type == 'buy').PARTITION(name="customer_group", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="distinct_tickers", by=(ticker_id)).CALCULATE(
    ticker_id=ticker_id
)

sales_by_model = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    num_sales=COUNT(Cars.sale_records)
)

avg_days_to_payment = Dealership.CALCULATE(
    average_days=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

result = Sales.WHERE(
    HAS(
        car.inventory_snapshots.WHERE(
            (is_in_inventory == False) & (snapshot_date == sale_date)
        )
    ) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

cash_salespersons = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Salespersons.CALCULATE(
    first_name=first_name,
    last_name=last_name,
    total_sales_count=COUNT(sales_made.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 30)),
    total_revenue_amount=SUM(sales_made.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 30).sale_price)
).WHERE(
    total_sales_count > 0
).TOP_K(
    5, by=total_sales_count.DESC()
)

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

result = Sales.WHERE(
    YEAR(sale_date) == 2023
).CALCULATE(
    customer_state=customer.state,
    quarter_start_date=IFF(
        MONTH(sale_date) <= 3, "2023-01-01",
        IFF(
            MONTH(sale_date) <= 6, "2023-04-01",
            IFF(
                MONTH(sale_date) <= 9, "2023-07-01", 
                "2023-10-01"
            )
        )
    )
).PARTITION(
    name="state_quarter_groups", 
    by=("customer_state", "quarter_start_date")
).CALCULATE(
    state=customer_state,
    quarter=quarter_start_date,
    total_sales=SUM(Sales.sale_price)
)

cars_in_inventory_latest_snapshot = Dealership.CALCULATE(
    latest_date=MAX(
        InventorySnapshots.WHERE(
            (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
        ).snapshot_date
    )
).InventorySnapshots.WHERE(
    (snapshot_date == latest_date) & (is_in_inventory == True)
).car.CALCULATE(
    _id=_id,
    make=make,
    model=model,
    year=year
)

avg_ddd_per_drug = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            (HAS(end_dt) == 1) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_val=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_val
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), "@gmail.com") | ENDSWITH(LOWER(email), "@yahoo.com")
        )
    )
)

filtered_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatments_last_6_months = Patients.WHERE(first_name == "Alice").CALCULATE(
    num_treatments=COUNT(treatments_received.WHERE(
        (start_dt >= DATETIME('now', 'start of month', '-6 months')) &
        (start_dt < DATETIME('now', 'start of month'))
    ))
)

avg_weight_drugalin = DermTreatment.CALCULATE(
    avg_weight=AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

caw_male_patients = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

pic_for_female_patients = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == 'Female') & (ins_type == 'private')))
)

result = Drugs.WHERE(drug_type == 'biologic').treatments_used_in.doctor.PARTITION(name="states", by=loc_state).CALCULATE(
    state=loc_state
).ORDER_BY(loc_state.ASC())

pasi_score_by_insurance = Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=(insurance_type)
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score_day_100=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(5, by=avg_pasi_score_day_100.ASC())

top_specialties_by_drug_amount = Treatments.WHERE(
    start_dt >= DATETIME('now', '-6 months')
).CALCULATE(
    speciality=doctor.speciality
).PARTITION(
    name="specialty_groups", by=(speciality)
).CALCULATE(
    speciality=speciality,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(3, by=total_drug_amount.DESC())

recent_psoriasis_treatments_count = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (HAS(drug.fda_appr_dt) == 1) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6) &
            (end_dt <= DATETIME('now'))
        )
    )
)

result = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (gender == "male") & (ins_type == "private")
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    )
)

lub_per_user = Users.CALCULATE(
    user_id=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

result = Ewallet.CALCULATE(
    TUC=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

merchants_with_received_transactions = Merchants.WHERE(HAS(transactions_received) == 1).CALCULATE(
    mid=mid
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(notification_type == 'transaction').PARTITION(name="distinct_users", by=(user_id)).CALCULATE(
    user_id=user_id
)

top_merchants_by_amount = Transactions.WHERE(
    (receiver_type == 1) & (DATEDIFF("days", created_at, DATETIME('now')) <= 150)
).PARTITION(
    name="merchant_groups", by=(receiver_id)
).CALCULATE(
    merchant_name=MIN(Transactions.receiving_merchant.name),
    total_num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(2, by=total_transaction_amount.DESC())

median_merchant_balance = Ewallet.CALCULATE(
    median_balance=MEDIAN(
        Merchants.WHERE(
            (status == 'active') & CONTAINS(LOWER(category), 'retail')
        ).balances.balance
    )
)

result = UserSessions.PARTITION(name="sessions_by_device", by=(device_type)).CALCULATE(
    device_type=device_type,
    avg_session_duration_seconds=AVG(
        DATEDIFF("seconds", sessions_by_device.session_start_ts, sessions_by_device.session_end_ts)
    )
)
